import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, fetchDurationOptions, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: 'inprogress',
  });
  const [franchiseList, setFranchiseList] = useState([]);
  const [durationList, setDurationList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [userFullName, setUserFullName] = useState('');

  const validExamNames = [
    'ServiceNow: CAD', 'ServiceNow: CSA', 'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION', 'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer', 'Salesforce administrators', 'Google cloud', 
    'Mulesoft', 'Fusion', 'PSI'
  ];

  const validStatuses = ['completed', 'absent', 'inprogress'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [franchiseData, durationData] = await Promise.all([
          getAssociatedFranchises(),
          fetchDurationOptions(),
        ]);

        if (!Array.isArray(franchiseData) || franchiseData.length === 0) {
          throw new Error('No associated franchises found for the user.');
        }

        if (!Array.isArray(durationData.options) || durationData.options.length === 0) {
          throw new Error('No exam durations available.');
        }

        setFranchiseList(franchiseData[0]);
        setDurationList(durationData.options);
        setExamData((prevData) => ({
          ...prevData,
          franchiseId: franchiseData[0]._id || '',
        }));
      } catch (error) {
        setError(error.message || 'Failed to fetch data.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setExamData((prevData) => ({
      ...prevData,
      [name]: name === 'durationInMinutes' ? parseInt(value, 10) : value,
    }));
  };

  const validateForm = () => {
    if (!examData.examName || !validExamNames.includes(examData.examName)) {
      return 'Please select a valid exam name.';
    }
    if (!examData.status || !validStatuses.includes(examData.status.toLowerCase())) {
      return 'Please select a valid status.';
    }
    if (!examData.date) {
      return 'Please provide the exam date.';
    }
    if (isNaN(new Date(examData.date).getTime())) {
      return 'Invalid date format.';
    }
    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) {
      return 'Please select a valid exam duration.';
    }
    if (!userFullName) {
      return 'Please provide a full name.';
    }
    return null;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      const payload = {
        examData: [
          {
            franchiseId: examData.franchiseId,
            name: userFullName,
            examName: examData.examName,
            date: new Date(examData.date).toISOString().split('T')[0],
            durationInMinutes: examData.durationInMinutes,
            status: examData.status.toLowerCase(),
          },
        ],
      };

      await createUserExamData(payload);
      setSuccess('Exam data created successfully!');

      setExamData({
        franchiseId: examData.franchiseId,
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress',
      });
      setUserFullName('');
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise</h2>
      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleSubmit} style={styles.form}>
        <FormGroup label="Select Franchise" name="franchiseId" value={examData.franchiseId} onChange={handleChange} options={franchiseList} />
        <FormGroup label="Full Name" name="userFullName" value={userFullName} onChange={(e) => setUserFullName(e.target.value)} type="text" />
        <FormGroup label="Exam Name" name="examName" value={examData.examName} onChange={handleChange} options={validExamNames} />
        <FormGroup label="Exam Date" name="date" value={examData.date} onChange={handleChange} type="date" />
        <FormGroup label="Duration (Minutes)" name="durationInMinutes" value={examData.durationInMinutes} onChange={handleChange} options={durationList} />
        <FormGroup label="Status" name="status" value={examData.status} onChange={handleChange} options={validStatuses} />

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

const FormGroup = ({ label, name, value, onChange, options = [], type = 'select' }) => (
  <div style={styles.formGroup}>
    <label htmlFor={name} style={styles.label}>{label}</label>
    {type === 'select' ? (
      <select name={name} value={value} onChange={onChange} required style={styles.input}>
        <option value="">Select {label.toLowerCase()}</option>
        {options.map((option, index) => (
          <option key={index} value={option._id || option}>{option.name || option}</option>
        ))}
      </select>
    ) : (
      <input type={type} name={name} value={value} onChange={onChange} required style={styles.input} />
    )}
  </div>
);

const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  header: {
    fontSize: '2rem',
    textAlign: 'center',
    marginBottom: '20px',
  },
  formTitle: {
    fontSize: '1.5rem',
    marginBottom: '15px',
    textAlign: 'center',
  },
  form: {
    width: '100%',
    maxWidth: '500px',
    padding: '20px',
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
  },
  formGroup: {
    marginBottom: '15px',
  },
  label: {
    display: 'block',
    marginBottom: '8px',
    fontSize: '1rem',
  },
  input: {
    width: '100%',
    padding: '10px',
    fontSize: '1rem',
    border: '1px solid #ccc',
    borderRadius: '4px',
    boxSizing: 'border-box',
  },
  submitButton: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    cursor: 'pointer',
    fontSize: '1.1rem',
    transition: 'background-color 0.3s ease',
  },
  loading: {
    textAlign: 'center',
    fontSize: '1.2rem',
    color: '#007bff',
  },
  error: {
    color: 'red',
    fontSize: '1.1rem',
    textAlign: 'center',
  },
  success: {
    color: 'green',
    fontSize: '1.1rem',
    textAlign: 'center',
  },
};

export default AssociatedFranchises;
